#include "cell_guard.h"
#include <stdio.h>
#include <string.h>
#include <sched.h>
#include <time.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"OW_CHECK OCG line%d: %s\n",__LINE__,#x);return 1;}}while(0)
static int base(void){OwCell c={0};c.value=9;c.borrows.extent=1;OwToken a,b;int32_t old=71;CHECK(ow_borrow(&c.borrows,0,1,0,&a)==OW_OK&&ow_borrow(&c.borrows,0,1,0,&b)==OW_OK);CHECK(ow_cell_write(&c,a,7)==OW_INVALID&&c.value==9);CHECK(ow_cell_replace(&c,4,&old)==OW_BUSY&&old==71&&c.value==9);CHECK(ow_release(&c.borrows,b)==OW_OK&&ow_release(&c.borrows,a)==OW_OK);CHECK(ow_cell_read(&c,a,&old)==OW_STALE&&old==71);CHECK(ow_borrow(&c.borrows,1,0,1,&a)==OW_OK&&ow_cell_read(&c,a,&old)==OW_INVALID&&old==71);CHECK(ow_release(&c.borrows,a)==OW_OK);CHECK(ow_cell_replace(&c,4,&old)==OW_OK&&old==9&&c.value==4);CHECK(ow_borrow(&c.borrows,0,1,0,&a)==OW_OK);int32_t *escaped=&c.value;*escaped=88;CHECK(ow_cell_read(&c,a,&old)==OW_OK&&old==88);CHECK(ow_release(&c.borrows,a)==OW_OK);puts("OCG_BASE actual-cell shared-writer empty-guard replacement-canary raw-alias-bypass");return 0;}
static int orders(void){unsigned cases=0;for(unsigned a=0;a<4;++a)for(unsigned b=0;b<4;++b)for(unsigned d=0;d<4;++d)for(unsigned e=0;e<4;++e){unsigned p[4]={a,b,d,e};if(a==b||a==d||a==e||b==d||b==e||d==e)continue;OcgCell c;CHECK(ocg_init(&c,7)==0);OcgToken t[4];for(unsigned i=0;i<4;++i)CHECK(ocg_acquire(&c,0,&t[i])==OW_OK);int32_t out=91;for(unsigned i=0;i<4;++i){CHECK(ocg_replace(&c,9,&out)==OW_BUSY&&out==91);CHECK(ocg_release(&c,t[p[i]])==OW_OK);}CHECK(ocg_replace(&c,9,&out)==OW_OK&&out==7);CHECK(ocg_destroy(&c)==OW_OK);++cases;}CHECK(cases==24);puts("OCG_ORDERS all24-reader-release-permutations");return 0;}
typedef struct {OcgCell *cell;unsigned calls,bad,fail,close;} Callback;
static int reenter(void *p,int32_t old,int32_t *candidate){Callback *x=p;++x->calls;OcgToken reader;OwStatus s=ocg_acquire(x->cell,0,&reader);if(s!=OW_BUSY)x->bad=1;if(s==OW_OK)(void)ocg_release(x->cell,reader);int32_t prior=91;if(ocg_replace(x->cell,77,&prior)!=OW_BUSY||prior!=91)x->bad=1;prior=91;if(ocg_update(x->cell,reenter,x,&prior)!=OW_BUSY||prior!=91)x->bad=1;if(x->close&&ocg_close(x->cell)!=OW_OK)x->bad=1;*candidate=old+3;return x->fail?1:0;}
static int callbacks(void){OcgCell c;CHECK(ocg_init(&c,9)==0);Callback x={&c,0,0,0,0};int32_t old=71;CHECK(ocg_update(&c,reenter,&x,&old)==OW_OK&&old==9&&!x.bad&&x.calls==1);x.fail=1;old=71;CHECK(ocg_update(&c,reenter,&x,&old)==OW_INVALID&&old==71&&x.calls==2&&!x.bad);OcgToken t;CHECK(ocg_acquire(&c,0,&t)==OW_OK&&ocg_read(&c,t,&old)==OW_OK&&old==12&&ocg_release(&c,t)==OW_OK);CHECK(ocg_destroy(&c)==OW_OK);puts("OCG_CALLBACK retained-writer rejects-reentry failure-keeps-value effects-remain");return 0;}
static int closing(void){OcgCell c;CHECK(ocg_init(&c,9)==0);Callback x={&c,0,0,0,1};int32_t old=71;CHECK(ocg_update(&c,reenter,&x,&old)==OW_DEAD&&old==71&&c.cell.value==9&&!c.updating&&x.calls==1);OcgToken t={NULL,{91,92}};CHECK(ocg_acquire(&c,0,&t)==OW_DEAD&&t.token.slot==91);CHECK(ocg_destroy(&c)==OW_OK);CHECK(ocg_init(&c,5)==0);CHECK(ocg_acquire(&c,1,&t)==OW_OK&&ocg_close(&c)==OW_OK);CHECK(ocg_read(&c,t,&old)==OW_OK&&old==5&&ocg_write(&c,t,6)==OW_OK);CHECK(ocg_destroy(&c)==OW_BUSY&&ocg_release(&c,t)==OW_OK&&ocg_destroy(&c)==OW_OK);puts("OCG_CLOSE callback-before-commit-refusal existing-guard-drains");return 0;}
static int identity(void){OcgCell a,b;CHECK(ocg_init(&a,7)==0&&ocg_init(&b,8)==0);OcgToken x,y;CHECK(ocg_acquire(&a,1,&x)==OW_OK&&ocg_acquire(&b,1,&y)==OW_OK);int32_t out=91;CHECK(ocg_read(&b,x,&out)==OW_STALE&&out==91);CHECK(ocg_release(&a,x)==OW_OK);OcgToken stale=x;CHECK(ocg_acquire(&a,1,&x)==OW_OK&&ocg_read(&a,stale,&out)==OW_STALE&&out==91);CHECK(ocg_release(&a,x)==OW_OK&&ocg_release(&b,y)==OW_OK);for(unsigned i=0;i<4;++i)a.cell.borrows.loan[i].serial=UINT32_MAX;a.cell.borrows.loan[0].serial=UINT32_MAX-1;CHECK(ocg_acquire(&a,1,&x)==OW_OK&&x.token.serial==UINT32_MAX);CHECK(ocg_release(&a,x)==OW_OK&&ocg_acquire(&a,0,&x)==OW_FULL);CHECK(ocg_destroy(&a)==OW_OK&&ocg_destroy(&b)==OW_OK);puts("OCG_IDENTITY cross-cell stale maximum-final-release");return 0;}
static int plus_one(void *p,int32_t old,int32_t *candidate){(void)p;*candidate=old+1;return 0;}
typedef struct {OcgCell *cell;unsigned accepted,busy,failed;} Worker;
static void *worker(void *p){Worker *w=p;for(unsigned tries=0;tries<1000000&&w->accepted<1000;++tries){int32_t old;OwStatus s=ocg_update(w->cell,plus_one,NULL,&old);if(s==OW_OK)++w->accepted;else if(s==OW_BUSY){++w->busy;sched_yield();}else{w->failed=1;break;}}return NULL;}
static int threads(void){OcgCell c;CHECK(ocg_init(&c,0)==0);Worker w[4]={{&c,0,0,0},{&c,0,0,0},{&c,0,0,0},{&c,0,0,0}};pthread_t t[4];for(unsigned i=0;i<4;++i)CHECK(pthread_create(&t[i],NULL,worker,&w[i])==0);unsigned busy=0;for(unsigned i=0;i<4;++i){CHECK(pthread_join(t[i],NULL)==0&&w[i].accepted==1000&&!w[i].failed);busy+=w[i].busy;}OcgToken reader;int32_t out;CHECK(ocg_acquire(&c,0,&reader)==OW_OK&&ocg_read(&c,reader,&out)==OW_OK&&out==4000);CHECK(ocg_release(&c,reader)==OW_OK&&ocg_destroy(&c)==OW_OK);printf("OCG_THREADS actual-four-pthreads accepted4000 busy%u joined-before-destroy\n",busy);return 0;}
typedef struct {OcgCell *cell;pthread_mutex_t lock;pthread_cond_t changed;unsigned entered,resume;OwStatus status;int32_t old;} Paused;
static int pause_update(void *p,int32_t old,int32_t *candidate){Paused *x=p;pthread_mutex_lock(&x->lock);x->entered=1;pthread_cond_broadcast(&x->changed);while(!x->resume)pthread_cond_wait(&x->changed,&x->lock);pthread_mutex_unlock(&x->lock);*candidate=old+1;return 0;}
static void *paused_worker(void *p){Paused *x=p;x->status=ocg_update(x->cell,pause_update,x,&x->old);return NULL;}
static int close_thread(void){OcgCell c;CHECK(ocg_init(&c,5)==0);Paused p={.cell=&c,.lock=PTHREAD_MUTEX_INITIALIZER,.changed=PTHREAD_COND_INITIALIZER,.old=91};pthread_t thread;CHECK(pthread_create(&thread,NULL,paused_worker,&p)==0);pthread_mutex_lock(&p.lock);while(!p.entered)pthread_cond_wait(&p.changed,&p.lock);pthread_mutex_unlock(&p.lock);CHECK(ocg_close(&c)==OW_OK);pthread_mutex_lock(&p.lock);p.resume=1;pthread_cond_signal(&p.changed);pthread_mutex_unlock(&p.lock);CHECK(pthread_join(thread,NULL)==0&&p.status==OW_DEAD&&p.old==91&&c.cell.value==5);CHECK(ocg_destroy(&c)==OW_OK);CHECK(pthread_cond_destroy(&p.changed)==0&&pthread_mutex_destroy(&p.lock)==0);puts("OCG_ASYNC_CLOSE actual-paused-callback close-drain-join unchanged-value");return 0;}
static int oracle(void){unsigned readers,writer,fail,close;while(scanf("%u %u %u %u",&readers,&writer,&fail,&close)==4){OcgCell c;if(ocg_init(&c,9))return 1;OcgToken t[4];unsigned n=0;OwStatus a=OW_OK;for(unsigned i=0;i<readers;++i){OcgToken next;a=ocg_acquire(&c,(int)writer,&next);if(a==OW_OK)t[n++]=next;}Callback x={&c,0,0,fail,close};int32_t old=71;OwStatus u=ocg_update(&c,reenter,&x,&old);printf("%d %u %d %d %u %u %u\n",a,n,u,old,x.calls,x.bad,c.closed);for(unsigned i=0;i<n;++i)if(ocg_release(&c,t[i])!=OW_OK)return 1;if(ocg_destroy(&c)!=OW_OK)return 1;}return ferror(stdin)?2:0;}
static int metrics(void){OcgCell c;CHECK(ocg_init(&c,0)==0);unsigned sum=0;double times[7];for(unsigned s=0;s<7;++s){clock_t start=clock();for(unsigned i=0;i<10000;++i){int32_t old;CHECK(ocg_update(&c,plus_one,NULL,&old)==OW_OK);sum+=(unsigned)old;}times[s]=(double)(clock()-start)/CLOCKS_PER_SEC;}CHECK(ocg_destroy(&c)==OW_OK);printf("{\"iterations\":10000,\"checksum\":%u,\"cell_size\":%zu,\"allocation_calls\":0,\"seconds\":[",sum,sizeof(OcgCell));for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",times[i]);puts("]}");return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"cell_guard_base"))return base();if(!strcmp(argv[1],"cell_guard_orders"))return orders();if(!strcmp(argv[1],"cell_guard_callbacks"))return callbacks();if(!strcmp(argv[1],"cell_guard_close"))return closing();if(!strcmp(argv[1],"cell_guard_identity"))return identity();if(!strcmp(argv[1],"cell_guard_threads"))return threads();if(!strcmp(argv[1],"cell_guard_async_close"))return close_thread();if(!strcmp(argv[1],"oracle"))return oracle();if(!strcmp(argv[1],"metrics"))return metrics();return 2;}
